enforcement.policy:
// Compiled by legate-standard-compiler.v1 from the signed standard's structured requirements.
// The standard carries this file's digest (acta-policy-digest-v1). Edit the standard, not this file.
// Tool: submit_payment. Amounts are integer minor units of USD. The limit $250,000.00 is inclusive and per instruction.
// Everything else in the standard (who approved, how fresh, what the bank read back) is checked on the signed records, not here.

permit (
  principal,
  action == Action::"MCP::Tool::call",
  resource == Tool::"submit_payment"
) when {
  context has input &&
  context.input has amount_minor &&
  context.input has currency &&
  context.input.currency == "USD" &&
  context.input.amount_minor <= 25000000
};

forbid (
  principal,
  action == Action::"MCP::Tool::call",
  resource == Tool::"submit_payment"
) unless {
  context has input &&
  context.input has amount_minor &&
  context.input has currency &&
  context.input.currency == "USD" &&
  context.input.amount_minor <= 25000000
};
